* DODF2 -- DODFMR Review / Delete Entered Service Periods
MAP DODF2 SIZE 24x80

  FIELD AT 1,18 LEN 45 PROT BRIGHT COLOR=TURQUOISE "DODFMR - REVIEW ENTERED PERIODS"

  FIELD AT 3,1  LEN 78 PROT COLOR=BLUE " #   FROM        TO          BR  CP  REASON  LOST"

  FIELD AT 4,1  LEN 78 PROT COLOR=BLUE "---- ----------  ----------  --  --  ------  -----"

* Data lines - 10 slots so we can grow beyond the original 8
  INPUT LINE01 AT 5,1  LEN 78 PROT COLOR=GREEN
  STOP      AT 5,79
  INPUT LINE02 AT 6,1  LEN 78 PROT COLOR=GREEN
  STOP      AT 6,79
  INPUT LINE03 AT 7,1  LEN 78 PROT COLOR=GREEN
  STOP      AT 7,79
  INPUT LINE04 AT 8,1  LEN 78 PROT COLOR=GREEN
  STOP      AT 8,79
  INPUT LINE05 AT 9,1  LEN 78 PROT COLOR=GREEN
  STOP      AT 9,79
  INPUT LINE06 AT 10,1 LEN 78 PROT COLOR=GREEN
  STOP      AT 10,79
  INPUT LINE07 AT 11,1 LEN 78 PROT COLOR=GREEN
  STOP      AT 11,79
  INPUT LINE08 AT 12,1 LEN 78 PROT COLOR=GREEN
  STOP      AT 12,79
  INPUT LINE09 AT 13,1 LEN 78 PROT COLOR=GREEN
  STOP      AT 13,79
  INPUT LINE10 AT 14,1 LEN 78 PROT COLOR=GREEN
  STOP      AT 14,79

  INPUT MSG    AT 16,1 LEN 78 PROT DIM COLOR=GREEN
  STOP      AT 16,79

* Selection area
  FIELD AT 18,1 LEN 12 PROT COLOR=GREEN "Selection:"
  INPUT SEL     AT 18,14 LEN 3  UNPROT COLOR=GREEN UNDERSCORE
  STOP           AT 18,17
  FIELD AT 18,18 LEN 40 PROT DIM "(enter number then PF5 to delete)"

* Status / help
  INPUT STATUS AT 20,1 LEN 78 PROT DIM COLOR=GREEN
  STOP      AT 20,79

* PF key legend
  FIELD AT 23,1 LEN 78 PROT COLOR=GREEN "PF3=Back to Entry   PF5=Delete   ENTER/PF6=Calculate   PF9=Clear All"

  CURSOR AT SEL
ENDMAP